head.script:
scwin.GRP_ID = "";
scwin.SEL_PJT_ID = "";

/**
 * 페이지 로드 이벤트
 */
scwin.onpageload = function () {
    // 1. 고정 대시보드 탭 추가
    tab_content.addTab("dashboardTab", {
        label: "HOME",
        closable: false,
        openAction: "select"
    }, {
        src: "dashboard.xml",
        frameMode: "wframe"
    });

    // 2. 페이지 로드 시 사이드바를 숨김 상태로 시작
    scwin.hideSidebar();
};

/**
 * 사이드바를 보여주는 함수
 */
scwin.showSidebar = function() {
    grp_menu.removeClass("closed");
};

/**
 * 사이드바를 숨기는 함수
 */
scwin.hideSidebar = function() {
    grp_menu.addClass("closed");
};

// 프로젝트 변경시 호출되는 공용 함수
scwin.onProjectChange = function (pjtId, grpId) {
    console.log("헤더로부터 프로젝트 변경 이벤트 발생: pjtId=" + pjtId);

    // 1. 프로젝트 ID 유무에 따라 사이드바 제어
    if (pjtId && pjtId !== "") {
        scwin.showSidebar();
    } else {
        scwin.hideSidebar();
    }

    // 2. 메뉴 목록을 가져오는 서브미션 실행
    scwin.SEL_PJT_ID = pjtId;
    scwin.GRP_ID = grpId ? grpId[0] : "";

    $c.sbm.execute(sbm_selectMenuList, {
        "elData": { "grpId": scwin.GRP_ID }
    });
};

/**
 * 웹스퀘어 Generator를 사용한 메뉴 생성 함수
 */
scwin.createMenuWithGenerator = function () {
    var genObj = gen_menu;
    genObj.removeAll(); // 기존 메뉴 제거

    var menuListLength = dlt_menuVoList.getRowCount();

    // 메뉴 데이터를 그룹화 (1뎁스 기준)
    var menuGroups = {};

    // 1뎁스와 2뎁스 메뉴를 분리하여 그룹화
    for (var i = 0; i < menuListLength; i++) {
        var menuData = dlt_menuVoList.getRowJSON(i);
        var parentId = menuData.parentMenuId || 'root';

        if (parentId === 'root' || parentId === '') {
            // 1뎁스 메뉴인 경우
            if (!menuGroups[menuData.menuId]) {
                menuGroups[menuData.menuId] = {
                    menu: menuData,
                    children: []
                };
            }
        } else {
            // 2뎁스 메뉴인 경우
            if (!menuGroups[parentId]) {
                menuGroups[parentId] = {
                    menu: null,
                    children: []
                };
            }
            menuGroups[parentId].children.push(menuData);
        }
    }

    // 그룹화된 메뉴 데이터로 실제 메뉴 DOM 생성
    for (var groupId in menuGroups) {
        var group = menuGroups[groupId];
        if (group.menu) {
            // 1뎁스 메뉴 생성
            var idx = genObj.insertChild();
            var menuObj = genObj.getChild(idx, "anc_menu");

            // 1뎁스 메뉴 설정
            menuObj.setValue(group.menu.menuName);
            menuObj.setUserData("menuId", group.menu.menuId);
            menuObj.setUserData("menuUrl", group.menu.menuUrl);
            menuObj.setUserData("hasChildren", group.children.length > 0 ? "Y" : "N");

            // 2뎁스 메뉴가 있는 경우 하위 메뉴 생성
            if (group.children.length > 0) {
                var subGenObj = genObj.getChild(idx, "gen_subMenu");
                for (var j = 0; j < group.children.length; j++) {
                    var childMenu = group.children[j];
                    var subIdx = subGenObj.insertChild();
                    var subMenuObj = subGenObj.getChild(subIdx, "anc_subMenu");

                    // 2뎁스 메뉴 설정
                    subMenuObj.setValue(childMenu.menuName);
                    subMenuObj.setUserData("menuId", childMenu.menuId);
                    subMenuObj.setUserData("menuUrl", childMenu.menuUrl);
                    subMenuObj.setUserData("parentId", childMenu.parentId);
                }
            }
        }
    }
};

/**
 * 1뎁스 메뉴 클릭 이벤트 핸들러
 */
scwin.menu_onclick = function () {
    var hasChildren = this.getUserData("hasChildren");
    var menuUrl = this.getUserData("menuUrl");

    if (hasChildren === "Y") {
        // 하위 메뉴 토글
        scwin.toggleSubMenu(this);
    } else if (menuUrl && menuUrl.trim() !== "") {
        // 단일 페이지 메뉴인 경우 탭으로 열기
        var menuName = this.getValue();
        scwin.openTab(menuUrl, menuName);
    }
};

/**
 * 2뎁스 메뉴 클릭 이벤트 핸들러
 */
scwin.submenu_onclick = function () {
    var menuUrl = this.getUserData("menuUrl");
    var menuName = this.getValue();

    if (menuUrl && menuUrl.trim() !== "") {
        scwin.openTab(menuUrl, menuName);
    }
};

/**
 * 하위 메뉴 토글 함수
 */
scwin.toggleSubMenu = function (menuObj) {
    var gen = menuObj.getGenerator();
    var idx = menuObj.getGeneratedIndex();
    var subNavObj = gen.getChild(idx, 'gen_subMenu');

    // 다른 모든 하위 메뉴 닫기 (아코디언 효과)
    for (var i = 0; i < gen.getLength(); i++) {
        if (i !== idx) {
            var otherSubNav = gen.getChild(i, 'gen_subMenu');
            otherSubNav.hide();
        }
    }

    // 현재 메뉴의 하위 메뉴 토글
    if (subNavObj.getStyle('display') === 'none' || !subNavObj.getStyle('display')) {
        subNavObj.show();
    } else {
        subNavObj.hide();
    }
};

/**
 * 탭 열기 함수
 */
scwin.openTab = function (url, title) {
    var tabId = "tab_" + new Date().getTime();

    try {
        // 중복 탭 확인
        var tabInfo = tab_content.getTabInfo();
        for (var i = 0; i < tabInfo.length; i++) {
            if (tabInfo[i] && tabInfo[i].src === url) {
                // 기존 탭으로 이동
                tab_content.setSelectedTabIndex(i);
                return;
            }
        }

        // 새 탭 생성
        tab_content.addTab(tabId, {
            "label": title,
            "closable": "true"
        }, {
            "src": url,
            "frameMode": "wframe"
        });

        tab_content.setSelectedTabIndex(tabId);

    } catch (e) {
        console.error("탭 생성 실패:", e);
        $c.win.alert("페이지를 로드할 수 없습니다: " + title);
    }
};

// 메뉴조회 콜백
scwin.sbm_selectMenuList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefined" || elHeader.resSuc === false) {
        $c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
        return false;
    }

    dlt_menuVoList.setJSON(elData.menuVo);
    // 웹스퀘어 Generator를 사용한 동적 메뉴 생성
    scwin.createMenuWithGenerator();
};
